function post_resto($no) {
  global $log;
  
  if (isset($log[$no])) {
    return $log[$no]['resto'];
  }
  
  $q = mysql_board_call('SELECT resto FROM `%s` WHERE no=%d', SQLLOG, $no);
  if (!mysql_num_rows($q)) {
    $log[$no] = array('resto' => false);
    return false;
  }
  $r = (int)mysql_fetch_row($q)[0];
  $log[$no] = array('resto' => $r);
  return $r;
  
  return false;
}

